function resultado(inicial, cambio) {
  let actual = inicial;
  if (cambio !== 0) {
    const actual = actual + cambio;
  }
  return actual;
}

function construirResultado(valorInicial, cambioTexto, bloqueado) {
  const inicial = Number(valorInicial);
  let actual = inicial;

  if (!bloqueado) {
    const actual = actual + Number(cambioTexto);
  }

  return {
    inicial,
    actual,
    diferencia: actual - inicial,
    bloqueado,
  };
}
